import six
from abc import ABCMeta
from taf.ue.plugin.mtk.executor import Executor
from taf.ue.plugin.mtk.exceptions import AtCommandExecuteFailure


@six.add_metaclass(ABCMeta)
class MaceExecutor(Executor):

    def __init__(self, mace):
        self._mace = mace


class MaceAtCommandExecutor(MaceExecutor):

    def __init__(self, mace):
        super(MaceAtCommandExecutor, self).__init__(mace)

    def execute(self, cmd=None, timeout=15, *args, **kwargs):
        output = self._mace.send_at_command(cmd)
        if not output:
            raise AtCommandExecuteFailure("failed to execute at command {}".format(cmd))
        return output


class MaceInjectMessageExecutor(MaceExecutor):

    class Parameter(object):
        message_id = 'MSG_ID_TST_INJECT_STRING'
        src_module = 'MOD_DHL'
        des_module = None
        sap = 'INVALID_SAP'
        local_param = {'index': 0, 'string': ''}

    def __init__(self, mace):
        super(MaceInjectMessageExecutor, self).__init__(mace)

    def execute(self, cmd=None, timeout=15, *args, **kwargs):
        parameters = self._split_command(cmd)
        return self._mace.inject_message(parameters.message_id,
                                         parameters.src_module,
                                         parameters.des_module,
                                         parameters.sap,
                                         parameters.local_param)

    @staticmethod
    def _split_command(cmd):
        param = MaceInjectMessageExecutor.Parameter()
        args = cmd.split(" ")
        param.des_module = args[0]
        param.local_param['index'] = int(args[1])
        param.local_param['string'] = args[2]
        return param


class RemotePopen(MaceExecutor):

    def __init__(self, mace):
        super(RemotePopen, self).__init__(mace)

    def execute(self, cmd=None, timeout=15, *args, **kwargs):
        return self._mace.run_shell_command(cmd)
